WITH scored AS (SELECT *, FIRST_VALUE(cost, TRUE) OVER (PARTITION BY status, order_id ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cost, LAST_VALUE(carrier, TRUE) OVER (PARTITION BY order_id ORDER BY delivered_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_carrier FROM shipments) SELECT CASE WHEN cost >= 91 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, DATE_TRUNC('WEEK', delivered_date) AS week_start, COUNT(*) AS cnt, SIZE(COLLECT_SET(status)) AS num_status FROM scored GROUP BY GROUPING SETS ((CASE WHEN cost >= 91 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('WEEK', delivered_date)), (CASE WHEN cost >= 91 THEN 'PREMIUM' ELSE 'STANDARD' END)) HAVING SIZE(COLLECT_SET(status)) >= 1
